(()=>{"use strict";(e=>{console.log(e);const t=document.getElementById("timer-hours"),n=document.getElementById("timer-minutes"),o=document.getElementById("timer-seconds"),s=()=>{let r=(()=>{let t=(new Date(e).getTime()-(new Date).getTime())/1e3;return{timeRemaining:t,screenHours:Math.floor(t/60/60),screenMinutes:Math.floor(t/60%60),screenSeconds:Math.floor(t%60)}})();t.textContent=r.screenHours,n.textContent=r.screenMinutes,o.textContent=r.screenSeconds,r.timeRemaining>0&&setTimeout(s,1e3)};s()})("21 december 2026")})();